{"command":"python3 - << 'PY'
import ast,re
inline=[]; block=[]; missing=[]
for line in open('/tmp/tags2.txt'):
    # format tag plain b'...' pretty b'...'
    m=re.match(r"(\S+) plain (b'.*?'|b\".*?\") pretty (b'.*'|b\".*\")\n$",line)
    if not m: print("parse fail",line); continue
    tag,plain,pretty=m.groups()
    plainv=ast.literal_eval(plain); prettyv=ast.literal_eval(pretty)
    if not plainv: missing.append(tag)
    elif prettyv==plainv: inline.append(tag)
    else:block.append(tag)
print("inline",inline)
print("block",block)
print("missing",missing)
PY"}

