#!/usr/bin/env python3
import os
import re
import sys
from html.entities import html5 as HTML5_ENTITIES

VERSION = "htmlq 0.4.0"

HTML_NS = "http://www.w3.org/1999/xhtml"
SVG_NS = "http://www.w3.org/2000/svg"
MATH_NS = "http://www.w3.org/1998/Math/MathML"
XLINK_NS = "http://www.w3.org/1999/xlink"
XML_NS = "http://www.w3.org/XML/1998/namespace"
XMLNS_NS = "http://www.w3.org/2000/xmlns/"
EMPTY_NS = ""

ASCII_WS = " \t\n\f\r"
RUST_WS = frozenset("\u0009\u000a\u000b\u000c\u000d\u0020\u0085\u00a0\u1680\u2000\u2001\u2002\u2003\u2004\u2005\u2006\u2007\u2008\u2009\u200a\u2028\u2029\u202f\u205f\u3000")

def is_rust_ws(s):
    return all(ch in RUST_WS for ch in s)

def split_ascii_ws(s):
    return [x for x in re.split(r"[ \t\n\f\r]+", s) if x != ""]

def ascii_lower(s):
    out = []
    for ch in s:
        o = ord(ch)
        out.append(chr(o + 32) if 65 <= o <= 90 else ch)
    return "".join(out)

def ascii_upper(s):
    out = []
    for ch in s:
        o = ord(ch)
        out.append(chr(o - 32) if 97 <= o <= 122 else ch)
    return "".join(out)

def eq_ascii_icase(a, b):
    return ascii_lower(a) == ascii_lower(b)

class Attr:
    __slots__ = ("ns", "prefix", "local", "value")
    def __init__(self, ns, prefix, local, value):
        self.ns = ns
        self.prefix = prefix
        self.local = local
        self.value = value
    def display(self):
        if self.prefix:
            return self.prefix + ":" + self.local
        return self.local

class Node:
    __slots__ = ("kind", "parent", "children", "data", "ns", "local", "prefix", "attrs", "template_contents")
    def __init__(self, kind, data=None, ns=None, local=None):
        self.kind = kind
        self.parent = None
        self.children = []
        self.data = data
        self.ns = ns
        self.local = local
        self.prefix = None
        self.attrs = {}
        self.template_contents = None

    def __repr__(self):
        if self.kind == "element":
            return f"<Node {self.local}>"
        return f"<Node {self.kind} {self.data!r}>"

    def append_child(self, child):
        if child.parent is not None:
            child.parent.children.remove(child)
        child.parent = self
        self.children.append(child)

    def insert_before(self, child, ref):
        if child.parent is not None:
            child.parent.children.remove(child)
        idx = self.children.index(ref)
        child.parent = self
        self.children.insert(idx, child)

    def detach(self):
        if self.parent is not None:
            try:
                self.parent.children.remove(self)
            except ValueError:
                pass
            self.parent = None

    def element_children(self):
        return [c for c in self.children if c.kind == "element"]

    def get_attr(self, ns, local):
        a = self.attrs.get((ns, local))
        return a.value if a is not None else None

    def set_attr(self, attr):
        self.attrs[(attr.ns, attr.local)] = attr

VOID_ELEMENTS = frozenset("area base basefont bgsound br col embed frame hr img input keygen link meta param source track wbr".split())
RAW_SERIALIZE_ELEMENTS = frozenset("script style xmp iframe noembed noframes noscript plaintext".split())
INLINE_ELEMENTS = frozenset(
    "ins del a abbr acronym audio b bdi bdo big button canvas cite code data datalist dfn em embed i iframe img input kbd label map mark meter noscript object output picture progress q ruby s samp script select slot small span strong sub sup svg template textarea time tt u var video wbr".split()
)

def escape_text(s, raw=False):
    if raw:
        return s
    return (s.replace("&", "&amp;")
             .replace("<", "&lt;")
             .replace(">", "&gt;")
             .replace("\u00a0", "&nbsp;"))

def escape_attr(s):
    return (s.replace("&", "&amp;")
             .replace('"', "&quot;")
             .replace("\u00a0", "&nbsp;"))

def opening_tag(node):
    parts = ["<", node.local]
    for key in sorted(node.attrs.keys(), key=lambda k: (k[0], k[1])):
        attr = node.attrs[key]
        parts.append(" ")
        parts.append(attr.display())
        parts.append('="')
        parts.append(escape_attr(attr.value))
        parts.append('"')
    parts.append(">")
    return "".join(parts)

def is_void(node):
    return node.kind == "element" and node.ns == HTML_NS and node.local in VOID_ELEMENTS

def serialize_plain(root):
    out = []
    # Iterative event traversal: stack items are (node, entered?)
    stack = [(root, False)]
    while stack:
        node, entered = stack.pop()
        if node.kind == "text":
            parent = node.parent
            raw = bool(parent is not None and parent.kind == "element" and parent.ns == HTML_NS and parent.local in RAW_SERIALIZE_ELEMENTS)
            out.append(escape_text(node.data, raw))
            continue
        if node.kind == "comment":
            out.append("<!--" + node.data + "-->")
            continue
        if node.kind != "element":
            # If somehow called with document/fragment (not used for selected nodes)
            for child in reversed(node.children):
                stack.append((child, False))
            continue
        if not entered:
            out.append(opening_tag(node))
            if is_void(node):
                continue
            stack.append((node, True))
            for child in reversed(node.children):
                stack.append((child, False))
        else:
            out.append("</" + node.local + ">")
    return "".join(out)

def serialize_pretty(root):
    out = []
    depth = 0
    flag = False  # the "indent next text / inline start" state inferred from the original
    stack = [(root, False)]
    while stack:
