            self._clear_to(("html", "tbody", "tfoot", "thead", "template"))
            self._make_element(Token("start", name="tr", attrs=[]), HTML_NS)
            self.mode = "in_row"
            self._process(tok); return
        if name in ("caption", "col", "colgroup", "tbody", "tfoot", "thead"):
            if self._has_in_scope(("tbody", "thead", "tfoot"), "table"):
                self._clear_to(("html", "table"))
                self._pop_until_name(("tbody", "thead", "tfoot"))
                self.mode = "in_table"
                self._process(tok)
            return
        # fall through
    if tok.kind == "end":
        name = tok.name
        if name in ("tbody", "tfoot", "thead"):
            if self._has_in_scope(name, "table"):
                self._clear_to(("html", "table"))
                self._pop_until_name(name)
