    if tok.kind == "comment":
        self._insert_comment(tok.data); return
    if tok.kind == "doctype":
        return
    if tok.kind == "eof":
        self._m_in_body(tok); return
    if tok.kind == "start":
        name = tok.name
        if name == "html":
            self._m_in_body(tok); return
        if name == "option":
            if _is_html_el(self._current(), ("option",)):
                self.stack.pop()
            self._make_element(tok, HTML_NS); return
        if name == "optgroup":
            if _is_html_el(self._current(), ("option",)):
                self.stack.pop()
            if _is_html_el(self._current(), ("optgroup",)):
                self.stack.pop()
            self._make_element(tok, HTML_NS); return
        if name == "select":
            # treat as </select>
            self._t_in_select(Token("end", name="select"), in_table); return
        if name in ("input", "keygen", "textarea"):
            has_select = False
            for n in reversed(self.stack):
                if _is_html_el(n, ("select",)):
                    has_select = True; break
                if n.kind == "element" and not _is_html_el(n, ("option", "optgroup")):
                    # select scope is permissive; keep scanning
                    pass
            if has_select:
                self._pop_until_name("select")
                self._reset_insertion_mode()
                self._process(tok)
            elif name == "textarea":
                pass
            return
        if name in ("script", "template"):
            self._m_in_head(tok); return
        return
    if tok.kind == "end":
        name = tok.name
        if name == "optgroup":
            # find matching
            idx = len(self.stack) - 1
            if idx >= 0 and _is_html_el(self.stack[idx], ("option",)) and idx > 0 and _is_html_el(self.stack[idx-1], ("optgroup",)):
                self.stack.pop()
            if _is_html_el(self._current(), ("optgroup",)):
                self.stack.pop()
            return
        if name == "option":
            if _is_html_el(self._current(), ("option",)):
                self.stack.pop()
            return
        if name == "select":
            has = False
            for i in range(len(self.stack)-1, -1, -1):
                n = self.stack[i]
                if _is_html_el(n, ("select",)):
                    has = True
