            if has:
                self._reset_insertion_mode()
            return
        if name == "template":
            self._m_in_head(tok); return
        if in_table and name in ("caption", "table", "tbody", "tfoot", "thead", "tr", "td", "th"):
            # may close the select and reprocess in table
            has = any(_is_html_el(n, ("select",)) for n in self.stack)
            if has:
                self._pop_until_name("select")
                self._reset_insertion_mode()
                self._process(tok)
            return
        return
    if in_table and tok.kind == "start" and tok.name in ("caption", "table", "tbody", "tfoot", "thead", "tr", "td", "th"):
