    if tok.kind == "start":
        name = tok.name
        if name in HEAD_LIKE or name in ("base", "basefont", "bgsound", "link", "meta"):
            self._m_in_head(tok); return
        if name in ("caption", "colgroup", "tbody", "tfoot", "thead"):
            if self.template_modes:
                self.template_modes[-1] = "in_table"
            self.mode = "in_table"; self._process(tok); return
        if name == "col":
            if self.template_modes:
                self.template_modes[-1] = "in_column_group"
            self.mode = "in_column_group"; self._process(tok); return
        if name == "tr":
            if self.template_modes:
                self.template_modes[-1] = "in_table_body"
            self.mode = "in_table_body"; self._process(tok); return
        if name in ("td", "th"):
            if self.template_modes:
                self.template_modes[-1] = "in_row"
            self.mode = "in_row"; self._process(tok); return
        if self.template_modes:
            self.template_modes[-1] = "in_body"
        self.mode = "in_body"; self._process(tok); return
    if tok.kind == "end":
        if tok.name == "template":
            self._m_in_head(tok); return
        return
    if tok.kind == "eof":
        has_template = any(_is_html_el(n, ("template",)) for n in self.stack)
        if not has_template:
            self.finished = True; return
        # pop everything up to template, then reprocess EOF
        self._generate_all_implied_thorough()
        self._pop_until_name("template")
        self._clear_active_to_marker()
        if self.template_modes:
            self.template_modes.pop()
        self._reset_insertion_mode()
        self._process(tok); return

def _t_in_frameset(self, tok):
    if tok.kind == "chars":
