        if name == "frame":
            self._make_element(tok, HTML_NS, push=False); return
        if name == "noframes":
            self._m_in_head(tok); return
        return
    if tok.kind == "end" and tok.name == "frameset":
        if _is_html_el(self._current(), ("html",)):
            return
        if self.stack:
            self.stack.pop()
        cur = self._current()
        if cur is not None and not _is_html_el(cur, ("frameset",)):
            self.mode = "after_frameset"
        return
    if tok.kind == "eof":
        if _is_html_el(self._current(), ("html",)):
            self.finished = True; return
        if _is_html_el(self._current(), ("frameset",)):
            self.stack.pop()
        cur = self._current()
