        if data:
            self._insert_text(data)
        return
    if tok.kind == "comment":
        if after_after:
            self._insert_comment(tok.data, override_parent=self.document)
        else:
            self._insert_comment(tok.data)
        return
    if tok.kind == "doctype":
        return
    if tok.kind == "start":
        if tok.name == "html":
            self._m_in_body(tok); return
        if tok.name == "noframes":
            self._m_in_head(tok); return
        return
    if tok.kind == "end" and tok.name == "html" and not after_after:
        self.mode = "after_after_frameset"; return
    if tok.kind == "eof":
        self.finished = True; return

def _t_after_body(self, tok, after_after=False):
    if tok.kind == "chars" and all(c in " \t\n\f\r" for c in tok.data.replace("\x00", "")):
        self._m_in_body(tok); return
    if tok.kind == "comment":
        if after_after:
            self._insert_comment(tok.data, override_parent=self.document)
        else:
            html_el = self.stack[0] if self.stack else self.document
            self._insert_comment(tok.data, override_parent=html_el)
        return
    if tok.kind == "doctype":
        return
    if tok.kind == "start" and tok.name == "html":
        self._m_in_body(tok); return
    if tok.kind == "end" and tok.name == "html" and not after_after:
        self.mode = "after_after_body"; return
    if tok.kind == "eof":
        self.finished = True; return
    self.mode = "in_body"
