def _t_text(self, tok):
    if tok.kind == "chars":
        if tok.data:
            self._insert_text(tok.data)
        return
    if tok.kind == "eof":
        # pop the text element and reprocess
        if self.stack:
            self.stack.pop()
        self.mode = self.original_mode or "in_body"
        self.tok_state = "data"
        self._process(tok); return
    if tok.kind == "end":
        if self.stack:
            self.stack.pop()
        self.mode = self.original_mode or "in_body"
        self.tok_state = "data"
        return
    # start tags shouldn't arrive here (script nesting emits chars instead)
    return

def _t_clear_to(self, contexts):
    while self.stack:
        cur = self.stack[-1]
        if _is_html_el(cur, contexts):
            break
        self.stack.pop()

def _t_flush_pending(self):
    if not self.pending_table_chars:
        return
    data = "".join(self.pending_table_chars)
    ws_only = self.pending_table_chars_ws
    self.pending_table_chars = []
    self.pending_table_chars_ws = True
    if not data:
        return
    if ws_only:
        d = data.replace("\x00", "")
        if d:
            self._insert_text(d)
    else:
        # process as in-body characters with foster parenting
        saved = self.foster
        self.foster = True
        try:
            self._m_in_body(Token("chars", data=data))
        finally:
            self.foster = saved

def _t_in_table(self, tok):
    if tok.kind == "comment":
        saved = self.foster
        # comments in a table context are inserted normally
        self._insert_comment(tok.data); return
    if tok.kind == "doctype":
        return
    if tok.kind == "start":
        name = tok.name
        if name == "caption":
            self._clear_to(("html", "table", "template"))
            self.active.append(None)
            self._make_element(tok, HTML_NS)
            self.mode = "in_caption"; return
        if name == "colgroup":
            self._clear_to(("html", "table", "template"))
            self._make_element(tok, HTML_NS)
            self.mode = "in_column_group"; return
        if name == "col":
            self._clear_to(("html", "table", "template"))
            fake = Token("start", name="colgroup", attrs=[])
            self._make_element(fake, HTML_NS)
            self.mode = "in_column_group"
            self._process(tok); return
        if name in ("tbody", "tfoot", "thead"):
            self._clear_to(("html", "table", "template"))
            self._make_element(tok, HTML_NS)
            self.mode = "in_table_body"; return
        if name in ("td", "th", "tr"):
            self._clear_to(("html", "table", "template"))
            fake = Token("start", name="tbody", attrs=[])
            self._make_element(fake, HTML_NS)
            self.mode = "in_table_body"
            self._process(tok); return
        if name == "table":
            if self._has_in_scope("table", "table"):
                self._pop_until_name("table")
                self._reset_insertion_mode()
                self._process(tok)
            return
        if name in ("style", "script", "template"):
            self._m_in_head(tok); return
        if name == "input":
            tval = self._in_attr_value(tok, "type")
            if tval is not None and eq_ascii_icase(tval, "hidden"):
                self._make_element(tok, HTML_NS, push=False)
            else:
                self._t_anything_else(tok)
            return
        if name == "form":
            if self.form is not None:
                return
            if any(_is_html_el(n, ("template",)) for n in self.stack):
                return
            node = self._make_element(tok, HTML_NS, push=True)
            self.form = node
            # A form in a table is immediately popped off the stack.
            if node in self.stack:
                self.stack.remove(node)
            return
        self._t_anything_else(tok); return
    if tok.kind == "end":
        name = tok.name
        if name == "table":
            if self._has_in_scope("table", "table"):
                self._pop_until_name("table")
                self._reset_insertion_mode()
            return
        if name == "template":
            self._m_in_head(tok); return
        if name in ("body", "caption", "col", "colgroup", "frame", "head", "tbody", "td", "tfoot", "th", "thead", "tr"):
            return
        self._t_anything_else(tok); return
    if tok.kind == "eof":
        self._m_in_body(tok); return
    if tok.kind == "chars":
        # Handled via pending-table-char buffering in the driver; if we get
        # here the current node is not a table context node.
        self._m_in_body(tok); return

