        actual whitespace character was seen (comments don't count)."""
        saw = False
        while self.pos < self.n:
            c = self.s[self.pos]
            if c in " \t\n\f\r":
                saw = True
                self.pos += 1
                continue
            if c == "/" and self.pos + 1 < self.n and self.s[self.pos+1] == "*":
                end = self.s.find("*/", self.pos + 2)
                if end == -1:
                    self.pos = self.n
                else:
                    self.pos = end + 2
                continue
            break
        return saw

    def consume_name(self):
        # Consume a sequence of name code points / escapes.  Returns False if
        # nothing was consumed.
        vals = []
        seen = False
