            if c == "/" and self.pos + 1 < self.n and self.s[self.pos+1] == "*":
                break
            if c == "\\":
                if self.pos + 1 < self.n and self.s[self.pos+1] in "\n\f\r":
                    break
                ch = self._escape()
                vals.append(ch)
                seen = True
                continue
            if (c.isascii() and (c.isalnum() or c in "-_")) or (ord(c) >= 0x80):
                vals.append(c)
                self.pos += 1
                seen = True
                continue
            break
        return ("".join(vals) if seen else None)

    def _escape(self):
        # self.s[self.pos] == '\\'
        self.pos += 1
        if self.pos >= self.n:
            return "\ufffd"
        c = self.s[self.pos]
        if c in "0123456789abcdefABCDEF":
            j = self.pos
            count = 0
            while j < self.n and count < 6 and self.s[j] in "0123456789abcdefABCDEF":
                j += 1; count += 1
            value = int(self.s[self.pos:j], 16)
            self.pos = j
            # consume one whitespace terminator (CRLF counts as one)
            if self.pos < self.n and self.s[self.pos] in " \t\n\f\r":
                if self.s[self.pos] == "\r" and self.pos + 1 < self.n and self.s[self.pos+1] == "\n":
                    self.pos += 2
                else:
                    self.pos += 1
            if value == 0 or value > 0x10FFFF or 0xD800 <= value <= 0xDFFF:
                return "\ufffd"
