    tbefore = [e for e in before if same_type(e)]
    tafter = [e for e in after if same_type(e)]
    if kind == "first-of-type":
        return not tbefore
    if kind == "last-of-type":
        return not tafter
    if kind == "only-of-type":
        return not tbefore and not tafter
    if kind == "nth-child":
        return nth_matches(pseudo[1], pseudo[2], len(before) + 1)
    if kind == "nth-last-child":
        return nth_matches(pseudo[1], pseudo[2], len(after) + 1)
    if kind == "nth-of-type":
        return nth_matches(pseudo[1], pseudo[2], len(tbefore) + 1)
    if kind == "nth-last-of-type":
        return nth_matches(pseudo[1], pseudo[2], len(tafter) + 1)
    return False

def match_component(node, comp, doc):
    t = comp[0]
    if t == "type":
        _, ns, name = comp
        if ns == "":
            return False  # parsed elements always have a namespace
        # ns None (bare) or "*" (*|) match any namespace; "*" as a name too
        if name == "*":
            return True
        if node.ns == HTML_NS:
            return eq_ascii_icase(node.local, name)
        return node.local == name
    if t == "id":
        return get_plain_attr(node, "id") == comp[1]
    if t == "class":
        cls = get_plain_attr(node, "class")
        if cls is None:
            return False
        return comp[1] in split_ascii_ws(cls)
    if t == "attr":
        return match_attr_component(node, comp)
    if t == "pseudo":
        return match_pseudo(node, comp[1], doc)
    return False

def match_compound(node, compound, doc):
    if node.kind != "element":
        return False
    return all(match_component(node, c, doc) for c in compound)

def match_complex_at(node, parts, idx, doc):
    combinator, compound = parts[idx]
    if not match_compound(node, compound, doc):
        return False
    if idx == 0:
        return True
    comb = parts[idx][0]
    if comb == ">":
        p = element_parent(node)
        return p is not None and match_complex_at(p, parts, idx-1, doc)
    if comb == " ":
        p = element_parent(node)
        while p is not None:
            if match_complex_at(p, parts, idx-1, doc):
                return True
            p = element_parent(p)
        return False
    if comb == "+":
        s = prev_element_sibling(node)
        return s is not None and match_complex_at(s, parts, idx-1, doc)
    if comb == "~":
        for s in element_siblings_before(node):
            if match_complex_at(s, parts, idx-1, doc):
                return True
        return False
    return False

def element_matches(node, selector_list, doc):
    if node.kind != "element":
        return False
    for parts in selector_list:
        if match_complex_at(node, parts, len(parts)-1, doc):
            return True
    return False

# ---- traversal of the document in document order, Kuchiki-style ----

class EdgeTraverser:
    """A traversal mirroring the original's lazy select iterator.

    It stores a single next edge (Start/End of a node), computing the
    following edge from the current tree when an edge is taken.  Detaching
    a node during iteration therefore has the same observable knock-on
    effects as in the original, including not being able to climb out of
    a detached subtree through a node with children.
    """
    def __init__(self, root):
        self.root = root
        self.next_edge = ("start", root)

    def _first_child(self, node):
        return node.children[0] if node.children else None

    def _next_sibling(self, node):
        p = node.parent
        if p is None:
            return None
        try:
            i = p.children.index(node)
        except ValueError:
            return None
        return p.children[i+1] if i + 1 < len(p.children) else None

    def _attached(self, node):
        n = node
        while n is not None:
            if n is self.root:
                return True
            n = n.parent
        return False

    def take(self):
        edge = self.next_edge
        if edge is None:
            return None
        kind, node = edge
        if kind == "start":
            fc = self._first_child(node)
            if fc is not None:
                self.next_edge = ("start", fc)
            else:
                self.next_edge = ("end", node)
        else:
            if node is self.root:
                self.next_edge = None
            else:
                ns = self._next_sibling(node)
                if ns is not None:
                    self.next_edge = ("start", ns)
                else:
                    p = node.parent
                    # A parent in a detached subtree is only climbable if
                    # it is still reachable from the traversal root.
                    if p is not None and self._attached(p):
                        self.next_edge = ("end", p)
                    else:
                        self.next_edge = None
        return edge

    def __iter__(self):
        return self

    def __next__(self):
        # descendants: yield start edges of all nodes strictly below root
        while True:
            edge = self.take()
            if edge is None:
                raise StopIteration
            if edge[0] == "start" and edge[1] is not self.root:
                return edge[1]

def select_elements(document, selector_list):
    traverser = EdgeTraverser(document)
    for node in traverser:
        if node.kind == "element" and element_matches(node, selector_list, document):
            yield node

def inclusive_descendants(root):
    out = []
    stack = [root]
    while stack:
        node = stack.pop()
        out.append(node)
        for c in reversed(node.children):
            stack.append(c)
    return out

def descendant_texts(root):
    texts = []
    for node in inclusive_descendants(root):
        if node.kind == "text":
            texts.append(node.data)
    return texts
