# ---------------- URL handling (WHATWG-flavoured) ----------------

import unicodedata as _ud

class _UrlError(Exception):
    pass

_SPECIAL_PORTS = {"ftp": 21, "http": 80, "https": 443, "ws": 80, "wss": 443}
_SPECIAL_SCHEMES = frozenset(list(_SPECIAL_PORTS) + ["file"])

def _enc_bytes(enc_set_name, s):
    c0 = set(range(0x20)) | {0x7f}
    # encode sets from the URL standard (byte values in the UTF-8 encoding
    # above 0x7e are always encoded)
    sets = {
        "c0": c0,
        "fragment": c0 | {0x20, 0x22, 0x3c, 0x3e, 0x60},
        "query": c0 | {0x20, 0x22, 0x23, 0x3c, 0x3e},
        "special-query": c0 | {0x20, 0x22, 0x23, 0x3c, 0x3e, 0x27},
    }
    sets["path"] = sets["query"] | {0x5e, 0x60, 0x7b, 0x7d}
    sets["userinfo"] = sets["path"] | {0x2f, 0x3a, 0x3b, 0x3d, 0x40, 0x5b, 0x5c, 0x5d, 0x5e, 0x7c}
    sets["opaque-host"] = c0 | {0x20, 0x22, 0x23, 0x2f, 0x3a, 0x3c, 0x3e, 0x3f, 0x40, 0x5b, 0x5c, 0x5d, 0x5e, 0x7c}
    enc = sets[enc_set_name]
    out = []
    for b in s.encode("utf-8"):
        if b in enc or b > 0x7e:
            out.append("%{:02X}".format(b))
        else:
            out.append(chr(b))
    return "".join(out)

class Url:
    __slots__ = ("scheme", "cannot_be_base", "username", "password", "host", "port", "path", "opaque", "query", "fragment")
    def __init__(self, scheme):
        self.scheme = scheme
        self.cannot_be_base = False
        self.username = ""
        self.password = None
        self.host = None
        self.port = None
        self.path = []      # list of segments when not cannot_be_base
        self.opaque = ""    # string when cannot_be_base
        self.query = None
        self.fragment = None
    def clone(self):
        u = Url(self.scheme)
        u.cannot_be_base = self.cannot_be_base
        u.username = self.username
        u.password = self.password
        u.host = self.host
        u.port = self.port
        u.path = list(self.path)
        u.opaque = self.opaque
        u.query = self.query
        u.fragment = self.fragment
        return u
    def serialize(self):
        out = self.scheme + ":"
        if self.cannot_be_base:
            out += self.opaque
        else:
            if self.host is not None:
                out += "//"
                if self.username != "" or self.password is not None:
                    out += self.username
                    if self.password is not None:
                        out += ":" + self.password
                    out += "@"
                out += self.host
                if self.port is not None:
                    out += ":" + str(self.port)
            elif len(self.path) > 1 and self.path[0] == "":
                out += "/."
            for seg in self.path:
                out += "/" + seg
        if self.query is not None:
            out += "?" + self.query
        if self.fragment is not None:
            out += "#" + self.fragment
        return out

def _pct_decode_bytes(s):
    out = bytearray()
    i = 0
    raw = s.encode("utf-8")
    while i < len(raw):
        if raw[i:i+1] == b"%" and i + 2 < len(raw) + 1 and i + 2 <= len(raw) - 1 + 1 and i + 2 < len(raw) + 1:
            h = raw[i+1:i+3]
            if len(h) == 2:
                try:
                    out.append(int(h.decode("ascii"), 16))
                    i += 3
                    continue
                except Exception:
                    pass
        out.append(raw[i])
        i += 1
    return bytes(out)

def _domain_to_ascii(decoded):
    if decoded == "":
        return ""
    s = decoded.replace("\u3002", ".").replace("\uff0e", ".").replace("\uff61", ".")
    labels = s.split(".")
    out_labels = []
    for label in labels:
        if label == "":
            out_labels.append("")
            continue
        if all(ord(c) < 128 for c in label):
            out_labels.append(ascii_lower(label))
            continue
        lab = _ud.normalize("NFC", label.lower())
        # drop default-ignorable soft hyphen as UTS46 mapping does
        lab = lab.replace("\u00ad", "")
        try:
            puny = lab.encode("punycode").decode("ascii")
        except Exception:
            return None
        out_labels.append("xn--" + puny)
    return ".".join(out_labels)

def _parse_ipv4_number(text):
    if text == "":
        return None
    radix = 10
    t = text
    if len(t) >= 2 and t[0] == "0" and t[1] in "xX":
        radix = 16
        t = t[2:]
        if t == "":
            return 0
    elif len(t) >= 2 and t[0] == "0":
        radix = 8
        t = t[1:]
        if t == "":
            return 0
    digits = {10: "0123456789", 8: "01234567", 16: "0123456789abcdefABCDEF"}[radix]
    if any(c not in digits for c in t):
        return None
    try:
        return int(t, radix)
    except Exception:
        return None

def _ends_in_number(host):
    parts = host.split(".")
    if parts and parts[-1] == "":
        if len(parts) == 1:
            return False
        parts.pop()
    if not parts:
        return False
    last = parts[-1]
    if last != "" and all(c in "0123456789" for c in last):
        return True
    return _parse_ipv4_number(last) is not None

def _parse_ipv4(host):
    parts = host.split(".")
    if parts and parts[-1] == "" and len(parts) > 1:
        parts.pop()
    if len(parts) > 4:
        raise _UrlError("ipv4")
    nums = []
    for part in parts:
        if part == "":
            raise _UrlError("ipv4")
        v = _parse_ipv4_number(part)
        if v is None:
            raise _UrlError("ipv4")
        nums.append(v)
    for v in nums[:-1]:
        if v > 255:
            raise _UrlError("ipv4")
    if nums and nums[-1] >= (256 ** (5 - len(nums))):
        raise _UrlError("ipv4")
    addr = nums[-1] if nums else 0
    for i, v in enumerate(nums[:-1]):
        addr += v * (256 ** (3 - i))
    return "%d.%d.%d.%d" % ((addr >> 24) & 255, (addr >> 16) & 255, (addr >> 8) & 255, addr & 255)

def _parse_ipv6(text):
    try:
        import ipaddress
        addr = ipaddress.IPv6Address(text)
    except Exception:
        raise _UrlError("ipv6")
    # WHATWG serialises IPv6 as lowercase hex pieces (ipaddress' compressed
    # form matches this, including for v4-tail inputs).
    return "[" + addr.compressed + "]"

def _parse_host(host_str, scheme):
    is_special = scheme in _SPECIAL_SCHEMES
    if host_str.startswith("["):
        if not host_str.endswith("]"):
            raise _UrlError("host")
        return _parse_ipv6(host_str[1:-1])
    if is_special:
        raw = _pct_decode_bytes(host_str)
        try:
            decoded = raw.decode("utf-8")
        except UnicodeDecodeError:
            raise _UrlError("host")
        # forbidden host code points in a domain
        for c in decoded:
            if ord(c) <= 0x20 or ord(c) == 0x7f or c in "#/:<>?@[\\]^|":
                raise _UrlError("host")
        domain = _domain_to_ascii(decoded)
        if domain is None:
            raise _UrlError("host")
        for c in domain:
            if ord(c) <= 0x20 or ord(c) == 0x7f or c in "#/:<>?@[\\]^|":
                raise _UrlError("host")
        if _ends_in_number(domain):
            return _parse_ipv4(domain)
        return domain
    # opaque host
    for c in host_str:
        if ord(c) <= 0x20 or ord(c) == 0x7f or c in '"#/<=>?@[\\]^|`':
            # note: ':' is the port delimiter and handled by the caller
            if c == ":":
                pass
            raise _UrlError("host")
    return _enc_bytes("opaque-host", host_str)

def _split_frag(rest):
    idx = rest.find("#")
    if idx == -1:
        return rest, None
    return rest[:idx], _enc_bytes("fragment", rest[idx+1:])

def _split_query(rest, scheme):
    idx = rest.find("?")
    if idx == -1:
        return rest, None
    enc = "special-query" if scheme in _SPECIAL_SCHEMES else "query"
    return rest[:idx], _enc_bytes(enc, rest[idx+1:])

def _is_drive_letter(seg):
    return len(seg) == 2 and seg[0].isascii() and seg[0].isalpha() and seg[1] in ":|"

def _norm_drive(seg):
    if _is_drive_letter(seg):
        return seg[0] + ":"
    return seg

def _dot_kind(seg):
    low = ascii_lower(seg)
    if low in (".", "%2e"):
        return 1
    if low in ("..", ".%2e", "%2e.", "%2e%2e"):
        return 2
    return 0

def _shorten_path(url):
    if url.scheme == "file" and len(url.path) == 1 and _is_drive_letter(url.path[0]):
        return
    if url.path:
        url.path.pop()

def _parse_path_into(url, rest, initial_segments):
    rest, frag = _split_frag(rest)
    rest, query = _split_query(rest, url.scheme)
    url.query = query
    url.fragment = frag
    url.path = list(initial_segments)
    path_str = rest
    special = url.scheme in _SPECIAL_SCHEMES

    def is_delim(ch):
        return ch == "/" or (special and ch == "\\")

    if path_str == "":
        return
    starts_delim = is_delim(path_str[0])
    body = path_str[1:] if starts_delim else path_str
    if body == "":
        components = [""]
    else:
        components = []
        cur = []
        for ch in body:
            if is_delim(ch):
                components.append("".join(cur)); cur = []
            else:
                cur.append(ch)
        components.append("".join(cur))
    ends_delim = body != "" and is_delim(body[-1])
    for i, comp in enumerate(components):
        is_last_component = (i == len(components) - 1)
        dk = _dot_kind(comp)
        if dk == 2:
            _shorten_path(url)
            if is_last_component and not ends_delim:
                url.path.append("")
        elif dk == 1:
            if is_last_component and not ends_delim:
                url.path.append("")
        else:
            seg = comp
            if url.scheme == "file":
                seg = _norm_drive(seg)
            url.path.append(_enc_bytes("path", seg))

def _parse_authority(auth):
    username = ""
    password = None
    hostport = auth
    if "@" in auth:
        at = auth.rfind("@")
        userinfo = auth[:at]
        hostport = auth[at+1:]
        if ":" in userinfo:
            uname, pword = userinfo.split(":", 1)
            username = _enc_bytes("userinfo", uname)
            password = _enc_bytes("userinfo", pword)
            if password == "":
                password = None
        else:
            username = _enc_bytes("userinfo", userinfo)
    return username, password, hostport

def _parse_host_port(hostport, scheme):
    host_str = hostport
    port = None
    if hostport.startswith("["):
        end = hostport.find("]")
        if end == -1:
            raise _UrlError("host")
        host_str = hostport[:end+1]
        rest = hostport[end+1:]
        if rest:
            if not rest.startswith(":"):
                raise _UrlError("host")
            port = _parse_port(rest[1:], scheme)
    else:
        if ":" in hostport:
            host_str, port_str = hostport.split(":", 1)
            port = _parse_port(port_str, scheme)
    host = _parse_host(host_str, scheme)
    return host, port

def _parse_port(port_str, scheme):
    if port_str == "":
        return None
    if any(c not in "0123456789" for c in port_str):
        raise _UrlError("port")
    # rust-url rejects numbers that overflow u32 parses as well as > 65535
    digits = port_str.lstrip("0") or "0"
    if len(digits) > 5:
        raise _UrlError("port")
    value = int(digits)
    if value > 65535:
        raise _UrlError("port")
    if _SPECIAL_PORTS.get(scheme) == value:
        return None
    return value

def _parse_authority_and_rest(rest, scheme):
    url = Url(scheme)
    special = scheme in _SPECIAL_SCHEMES
    # authority end
    end = len(rest)
    for i, ch in enumerate(rest):
        if ch in "/?#" or (special and ch == "\\"):
            end = i
            break
    auth = rest[:end]
    remainder = rest[end:]
    username, password, hostport = _parse_authority(auth)
    url.username = username
    url.password = password
    host, port = _parse_host_port(hostport, scheme)
    if special and scheme != "file" and host == "":
        raise _UrlError("empty host")
    url.host = host
    url.port = port
    _parse_path_into(url, remainder, [])
    if special and not url.path:
        url.path = [""]
    return url

def _build_from_base(base):
    u = base.clone()
    u.fragment = None
    return u

def _parse_file(rest, base):
    url = Url("file")
    url.host = ""
    special_delims = "/\\"
    if len(rest) >= 2 and rest[0] in special_delims and rest[1] in special_delims:
        # file host state
        after = rest[2:]
        end = len(after)
        for i, ch in enumerate(after):
            if ch in "/\\?#":
                end = i
                break
        host_str = after[:end]
        remainder = after[end:]
        if _is_drive_letter(host_str):
            url.host = ""
            _parse_path_into(url, "/" + _norm_drive(host_str) + remainder, [])
        else:
            if host_str == "":
                url.host = ""
            else:
                host = _parse_host(host_str, "file")
                url.host = "" if eq_ascii_icase(host, "localhost") else host
            _parse_path_into(url, remainder, [])
        if not url.path:
            url.path = [""]
        return url
    if rest and rest[0] in special_delims:
        url.host = ""
        _parse_path_into(url, rest, [])
        if not url.path:
            url.path = [""]
        return url
    if base is not None and base.scheme == "file":
        url.host = base.host
        # if rest's first segment is a drive letter, path replaces
        first_seg = re.split(r"[/\\]", rest.split("?")[0].split("#")[0], 1)[0] if rest else ""
        if _is_drive_letter(first_seg):
            _parse_path_into(url, rest, [])
        else:
            segs = list(base.path)
            saved = url.path
            url.path = segs
            _shorten_path(url)
            segs = url.path
            url.path = saved
            _parse_path_into(url, rest, segs)
        if not url.path:
            url.path = [""]
        return url
    url.host = ""
    if rest == "":
        _parse_path_into(url, "", [""])
    else:
        _parse_path_into(url, "/" + rest if not (rest and rest[0] in special_delims) else rest, [])
    if not url.path:
        url.path = [""]
    return url

def _parse_relative(inp, base):
    if base is None:
        raise _UrlError("relative without base")
    if base.cannot_be_base:
        if inp.startswith("#"):
            u = base.clone()
            u.fragment = _enc_bytes("fragment", inp[1:])
            return u
        raise _UrlError("cannot-be-base")
    scheme = base.scheme
    special = scheme in _SPECIAL_SCHEMES
    if scheme == "file" and len(inp) >= 2 and inp[0] in "/\\" and inp[1] in "/\\":
        return _parse_file(inp, base)
    if len(inp) >= 2 and inp[0] in "/" and inp[1] == "/":
