    if any(c not in digits for c in t):
        return None
    try:
        return int(t, radix)
    except Exception:
        return None

def _ends_in_number(host):
    parts = host.split(".")
    if parts and parts[-1] == "":
        if len(parts) == 1:
            return False
        parts.pop()
    if not parts:
        return False
    last = parts[-1]
    if last != "" and all(c in "0123456789" for c in last):
        return True
    return _parse_ipv4_number(last) is not None

def _parse_ipv4(host):
    parts = host.split(".")
    if parts and parts[-1] == "" and len(parts) > 1:
        parts.pop()
    if len(parts) > 4:
        raise _UrlError("ipv4")
    nums = []
    for part in parts:
        if part == "":
            raise _UrlError("ipv4")
        v = _parse_ipv4_number(part)
        if v is None:
            raise _UrlError("ipv4")
        nums.append(v)
    for v in nums[:-1]:
        if v > 255:
            raise _UrlError("ipv4")
