class Url:
    __slots__ = ("scheme", "cannot_be_base", "username", "password", "host", "port", "path", "opaque", "query", "fragment")
    def __init__(self, scheme):
        self.scheme = scheme
        self.cannot_be_base = False
        self.username = ""
        self.password = None
        self.host = None
        self.port = None
        self.path = []      # list of segments when not cannot_be_base
        self.opaque = ""    # string when cannot_be_base
        self.query = None
        self.fragment = None
    def clone(self):
        u = Url(self.scheme)
        u.cannot_be_base = self.cannot_be_base
        u.username = self.username
        u.password = self.password
        u.host = self.host
        u.port = self.port
        u.path = list(self.path)
        u.opaque = self.opaque
        u.query = self.query
        u.fragment = self.fragment
        return u
    def serialize(self):
        out = self.scheme + ":"
        if self.cannot_be_base:
            out += self.opaque
        else:
            if self.host is not None:
                out += "//"
                if self.username != "" or self.password is not None:
                    out += self.username
                    if self.password is not None:
                        out += ":" + self.password
                    out += "@"
                out += self.host
                if self.port is not None:
                    out += ":" + str(self.port)
            elif len(self.path) > 1 and self.path[0] == "":
                out += "/."
            for seg in self.path:
                out += "/" + seg
        if self.query is not None:
            out += "?" + self.query
        if self.fragment is not None:
            out += "#" + self.fragment
        return out

def _pct_decode_bytes(s):
    out = bytearray()
    i = 0
    raw = s.encode("utf-8")
    while i < len(raw):
        if raw[i:i+1] == b"%" and i + 2 < len(raw) + 1 and i + 2 <= len(raw) - 1 + 1 and i + 2 < len(raw) + 1:
            h = raw[i+1:i+3]
            if len(h) == 2:
                try:
                    out.append(int(h.decode("ascii"), 16))
                    i += 3
                    continue
                except Exception:
                    pass
        out.append(raw[i])
        i += 1
    return bytes(out)

def _domain_to_ascii(decoded):
    if decoded == "":
        return ""
    s = decoded.replace("\u3002", ".").replace("\uff0e", ".").replace("\uff61", ".")
    labels = s.split(".")
    out_labels = []
    for label in labels:
        if label == "":
            out_labels.append("")
            continue
        if all(ord(c) < 128 for c in label):
            out_labels.append(ascii_lower(label))
            continue
        lab = _ud.normalize("NFC", label.lower())
        # drop default-ignorable soft hyphen as UTS46 mapping does
        lab = lab.replace("\u00ad", "")
        try:
            puny = lab.encode("punycode").decode("ascii")
        except Exception:
            return None
        out_labels.append("xn--" + puny)
    return ".".join(out_labels)

def _parse_ipv4_number(text):
    if text == "":
        return None
    radix = 10
    t = text
    if len(t) >= 2 and t[0] == "0" and t[1] in "xX":
        radix = 16
        t = t[2:]
        if t == "":
            return 0
    elif len(t) >= 2 and t[0] == "0":
        radix = 8
        t = t[1:]
        if t == "":
            return 0
    digits = {10: "0123456789", 8: "01234567", 16: "0123456789abcdefABCDEF"}[radix]
    if any(c not in digits for c in t):
        return None
    try:
        return int(t, radix)
    except Exception:
        return None

def _ends_in_number(host):
    parts = host.split(".")
    if parts and parts[-1] == "":
        if len(parts) == 1:
            return False
        parts.pop()
    if not parts:
        return False
    last = parts[-1]
    if last != "" and all(c in "0123456789" for c in last):
        return True
    return _parse_ipv4_number(last) is not None

def _parse_ipv4(host):
    parts = host.split(".")
    if parts and parts[-1] == "" and len(parts) > 1:
        parts.pop()
    if len(parts) > 4:
        raise _UrlError("ipv4")
    nums = []
    for part in parts:
        if part == "":
            raise _UrlError("ipv4")
        v = _parse_ipv4_number(part)
        if v is None:
            raise _UrlError("ipv4")
        nums.append(v)
    for v in nums[:-1]:
        if v > 255:
            raise _UrlError("ipv4")
    if nums and nums[-1] >= (256 ** (5 - len(nums))):
        raise _UrlError("ipv4")
    addr = nums[-1] if nums else 0
    for i, v in enumerate(nums[:-1]):
        addr += v * (256 ** (3 - i))
    return "%d.%d.%d.%d" % ((addr >> 24) & 255, (addr >> 16) & 255, (addr >> 8) & 255, addr & 255)

def _parse_ipv6(text):
    try:
