    s = s.strip("".join(chr(i) for i in range(0x21)))
    if base is not None and s == "":
        u = base.clone()
        u.fragment = None
        return u
    # scheme
    m = re.match(r"^([A-Za-z][A-Za-z0-9+.\-]*):(.*)$", s, re.DOTALL)
    if m:
        scheme = ascii_lower(m.group(1))
        rest = m.group(2)
        if scheme in _SPECIAL_SCHEMES and base is not None and base.scheme == scheme:
            if scheme != "file" and len(rest) >= 2 and rest[0] in "/\\" and rest[1] in "/\\":
                return _parse_authority_and_rest(rest[2:], scheme)
            return _parse_relative(rest, base)
        if scheme == "file":
