                i += 1
            return _parse_authority_and_rest(rest[i:], scheme)
        # non-special
        if rest.startswith("//"):
            return _parse_authority_and_rest(rest[2:], scheme)
        if rest.startswith("/"):
            u = Url(scheme)
            _parse_path_into(u, rest, [])
            return u
        u = Url(scheme)
        u.cannot_be_base = True
        path_part, frag = _split_frag(rest)
        path_part, query = _split_query(path_part, scheme)
        u.opaque = _enc_bytes("c0", path_part)
        u.query = query
        u.fragment = frag
        return u
    return _parse_relative(s, base)

