def write_fd(fd, data_bytes):
    # ignore write errors, as the original ignores writeln results
    try:
        view = memoryview(data_bytes)
        while view:
            try:
                n = os.write(fd, view)
            except (BlockingIOError, InterruptedError):
                continue
            except OSError:
                return
            if n == 0:
                return
            view = view[n:]
    except Exception:
        return

