        end = min(i + match_dist + 1, lb)
        for j in range(start, end):
            if not b_matches[j] and a[i] == b[j]:
                a_matches[i] = True
                b_matches[j] = True
                matches += 1
                break
    if matches == 0:
        return 0.0
    t = 0
    k = 0
    for i in range(la):
        if a_matches[i]:
            while not b_matches[k]:
                k += 1
            if a[i] != b[k]:
                t += 1
            k += 1
    t //= 2
    return (matches / la + matches / lb + (matches - t) / matches) / 3.0

def _jaro_winkler(a, b):
    j = _jaro(a, b)
    if j > 0.7:
        prefix = 0
        for i in range(min(len(a), len(b), 4)):
            if a[i] == b[i]:
                prefix += 1
            else:
                break
        j += prefix * 0.1 * (1.0 - j)
    return j

def did_you_mean(name):
    best = None
    best_conf = 0.0
    for cand in sorted(LONG_TO_DEF.keys()):
        conf = _jaro_winkler(name, cand)
        if conf > 0.8 and conf > best_conf:
            best_conf = conf
            best = cand
    return best

