    if used_set:
        frags = " ".join(usage_fragment(x) for x in sorted(used_set))
        usage = f"{prog} {frags}"
    else:
        usage = f"{prog} [FLAGS] [OPTIONS] [--] [selector]..."
    text = f"error: {message}\n"
    if suggestion:
        text += f"\tDid you mean \x1b[32m--\x1b[0m\x1b[32m{suggestion}\x1b[0m?\n"
    text += f"\nUSAGE:\n    {usage}\n\nFor more information try --help\n"
