def parse_cli(argv_bytes, prog):
    # argv_bytes excludes argv0
    used = []            # long names, in encounter order (may repeat)
    occurrences = []     # (long, value_bytes_or_None)
    selector_values = []
    i = 0
    args = argv_bytes
    trailing = False

    def note_usage(long):
        if long not in used:
            used.append(long)

    while i < len(args):
        tok = args[i]
        i += 1
        if trailing:
            selector_values.append(tok)
            continue
        if tok == b"--":
            trailing = True
            continue
        if len(tok) > 2 and tok.startswith(b"--"):
            # long option (any number of leading dashes are stripped)
            body = tok
            eq = body.find(b"=")
            if eq != -1:
                raw_name = body[:eq].lstrip(b"-")
                attached = body[eq+1:]
                has_attached = True
            else:
                raw_name = body.lstrip(b"-")
                attached = None
                has_attached = False
            name = _decode_long_name(raw_name) if raw_name else ""
            if name and name in LONG_TO_DEF:
                d = LONG_TO_DEF[name]
                if d[2] == "help":
                    out_stdout(help_text(prog))
                    raise CliExit(0)
                if d[2] == "version":
                    out_stdout(VERSION + "\n")
                    raise CliExit(0)
                note_usage(name)
                if d[2] == "flag":
                    occurrences.append((name, None))
                else:
                    # option / multi
                    if has_attached:
                        occurrences.append((name, attached))
                    else:
                        val = None
                        if i < len(args) and (not args[i].startswith(b"-") or args[i] == b"-"):
                            val = args[i]
                            i += 1
                        occurrences.append((name, val))
                continue
            # unknown long
            suggestion = did_you_mean(name) if name else None
            msg = f"Found argument '--{name}' which wasn't expected, or isn't valid in this context"
            cli_error(prog, msg, used, suggestion)
        elif len(tok) > 1 and tok.startswith(b"-") and not tok.startswith(b"--"):
            # short cluster
            rest = tok[1:]
            pos = 0
            while pos < len(rest):
                disp, blen, ch = _first_short_char(rest[pos:])
                if ch is None:
                    cli_error(prog, f"Found argument '-{disp}' which wasn't expected, or isn't valid in this context", used)
                pos += blen
                if ch == "h":
                    out_stdout(help_text(prog))
                    raise CliExit(0)
                if ch == "V":
                    out_stdout(VERSION + "\n")
                    raise CliExit(0)
                d = SHORT_TO_DEF.get(ch)
                if d is None:
                    cli_error(prog, f"Found argument '-{disp}' which wasn't expected, or isn't valid in this context", used)
                note_usage(d[0])
                if d[2] == "flag":
                    occurrences.append((d[0], None))
                    continue
                # option: rest of the cluster is the value, if any
                tail = rest[pos:]
                if tail:
                    if tail.startswith(b"="):
                        val = tail[1:]
                    else:
                        val = tail
                    occurrences.append((d[0], val))
                else:
                    val = None
                    if i < len(args) and (not args[i].startswith(b"-") or args[i] == b"-"):
                        val = args[i]
                        i += 1
                    occurrences.append((d[0], val))
                break
            continue
        else:
            selector_values.append(tok)
            continue
    # validation
    # counts
    occ_count = {}
    val_count = {}
    first_idx = {}
    for idx, (long, val) in enumerate(occurrences):
        occ_count[long] = occ_count.get(long, 0) + 1
        val_count[long] = val_count.get(long, 0) + (1 if val is not None else 0)
        first_idx.setdefault(long, idx)
    # candidates: (long, kind) where kind in missing/duplicate
    candidates = []
    for long, cnt in occ_count.items():
        d = LONG_TO_DEF[long]
        if d[2] in ("option", "multi") and val_count.get(long, 0) == 0:
            candidates.append((long, "missing"))
        elif d[2] != "multi" and cnt > 1:
            candidates.append((long, "duplicate"))
    if candidates:
        chosen = None
        # prefer a missing-value error for the last occurrence overall
        if occurrences:
            last_long, last_val = occurrences[-1]
            for long, kind in candidates:
                if long == last_long and kind == "missing" and last_val is None:
                    chosen = (long, kind)
                    break
        if chosen is None:
            candidates.sort(key=lambda lk: occurrences.index((lk[0], occurrences[first_idx[lk[0]]][1])) if False else first_idx[lk[0]])
            chosen = candidates[0]
        long, kind = chosen
        frag = usage_fragment(long)
        if kind == "missing":
            msg = f"The argument '{frag}' requires a value but none was supplied"
        else:
            msg = f"The argument '{frag}' was provided more than once, but cannot be used multiple times"
        cli_error(prog, msg, used)
    return occurrences, selector_values

def get_prog_name(argv0_bytes):
    if not argv0_bytes:
        return "htmlq"
    # Unix file_name
    s = argv0_bytes.rstrip(b"/")
    if not s:
        return "htmlq"
    comp = s.rsplit(b"/", 1)[-1]
    if comp in (b"", b".", b".."):
        return "htmlq"
    try:
        return comp.decode("utf-8")
    except UnicodeDecodeError:
        return "htmlq"

