    selector_str = " ".join(selector_vals)
    attribute = None
    if "attribute" in occ:
        # values_of iterates all values
        vals = [decode_value(v, True) for v in occ["attribute"] if v is not None]
        attribute = vals[0] if vals else None
    remove_vals = None
    if "remove-nodes" in occ:
        remove_vals = [decode_value(v, True) for v in occ["remove-nodes"] if v is not None]
    # "value_of" style fields
