    filename = None
    outputname = None
    if "base" in occ:
        base_str = decode_value([v for v in occ["base"] if v is not None][0], False)
    if "filename" in occ:
        filename = decode_value([v for v in occ["filename"] if v is not None][0], False)
    if "output" in occ:
