def select_all(document, tag_local):
    # document-order traversal yielding elements with the given local name
    traverser = EdgeTraverser(document)
    for node in traverser:
        if node.kind == "element" and ascii_lower(node.local) == tag_local:
            yield node

def run_queries(document, selector_list, remove_selector_list, attribute,
                text_mode, pretty, ignore_ws, base_url, out):
    for node in select_elements(document, selector_list):
        if remove_selector_list is not None:
            first = None
            for cand in inclusive_descendants(node):
                if cand.kind == "element" and element_matches(cand, remove_selector_list, document):
                    first = cand
                    break
            if first is not None:
                first.detach()
                continue
        # base rewriting for link-like elements
        if base_url is not None and node.local in ("a", "area", "link"):
            href_attr = node.attrs.get((EMPTY_NS, "href"))
            if href_attr is not None:
                joined = url_join(base_url, href_attr.value)
                href_attr.value = joined.serialize()
        if attribute is not None:
            a = node.attrs.get((EMPTY_NS, attribute))
            if a is not None:
                out.writeln(a.value)
        elif text_mode:
            for t in descendant_texts(node):
                if ignore_ws:
                    if not is_rust_ws(t):
                        out.writeln(t)
                else:
                    out.write_str(t)
            out.writeln("")
        elif pretty:
            out.writeln(serialize_pretty(node))
        else:
            out.writeln(serialize_plain(node))

