        if base_url is not None and node.local in ("a", "area", "link"):
            href_attr = node.attrs.get((EMPTY_NS, "href"))
            if href_attr is not None:
                joined = url_join(base_url, href_attr.value)
                href_attr.value = joined.serialize()
