import subprocess
import sys

BIN = os.environ.get("HTMLQ_BIN", os.path.join(os.path.dirname(__file__), "..", "executable"))

def run(args, inp=b"", **kw):
    if isinstance(inp, str):
        inp = inp.encode()
    return subprocess.run([BIN] + args, input=inp, capture_output=True, **kw)

def test_help_and_version():
    assert run(["--help"]).stdout.startswith(b"htmlq 0.4.0\nMichael Maclean <michael@mgdm.net>\nRuns CSS selectors on HTML\n")
    assert run(["--version"]).stdout == b"htmlq 0.4.0\n"
    assert run(["-V"]).stdout == b"htmlq 0.4.0\n"

def test_default_selector_is_html():
    assert run([], "<div>hi</div>").stdout == b"<html><head></head><body><div>hi</div></body></html>\n"

def test_simple_selector():
    assert run(["p"], "<p>one</p><p>two</p>").stdout == b"<p>one</p>\n<p>two</p>\n"

def test_selector_args_are_joined_with_space():
    assert run(["div", "span"], "<div><span>hi</span></div>").stdout == b"<span>hi</span>\n"

def test_text_mode():
    assert run(["-t", "div"], "<div>hello <b>world</b></div>").stdout == b"hello world\n"

def test_text_ignore_whitespace_prints_each_text_node():
    assert run(["-t", "-w", "div"], "<div>hi <b>there</b> </div>").stdout == b"hi \nthere\n\n"

def test_attribute_mode():
    assert run(["-a", "href", "a"], '<a href="/x">t</a><a>t2</a>').stdout == b"/x\n"

def test_pretty():
    assert run(["-p", "div"], "<div><p>a</p><p>b</p></div>").stdout == b"\n<div>\n  <p>a\n  </p>\n  <p>\n    b\n  </p>\n</div>\n"

def test_base_join():
    assert run(["-b", "http://example.com/dir/", "a"], '<a href="x.html">t</a>').stdout == b'<a href="http://example.com/dir/x.html">t</a>\n'

def test_detect_base():
    html = '<head><base href="http://example.com/sub/"></head><a href="x.html">t</a>'
    assert run(["-B", "a"], html).stdout == b'<a href="http://example.com/sub/x.html">t</a>\n'

def test_detect_base_falls_back_to_option():
    assert run(["-B", "-b", "http://fallback.example/", "a"], '<a href="x.html">t</a>').stdout == b'<a href="http://fallback.example/x.html">t</a>\n'

def test_remove_nodes():
    # Removing a descendant of the only selected element leaves no output for
    # that element (matching the original's iteration behaviour).
    assert run(["-r", "span", "--", "div"], "<div><span>gone</span> kept</div>").stdout == b""
    # ...while an unrelated selected element is unaffected.
    assert run(["-r", "span", "--", "p"], "<p>hi</p><span>x</span>").stdout == b"<p>hi</p>\n"

def test_invalid_selector_panics():
    p = run(["["], "<p>x</p>")
    assert p.returncode == 101
    assert b"Failed to parse CSS selector" in p.stderr

def test_unknown_option():
    p = run(["--unknown"])
    assert p.returncode == 1
    assert p.stderr.startswith(b"error: Found argument '--unknown' which wasn't expected")

def test_input_and_output_files(tmp_path):
    src = tmp_path / "in.html"
    dst = tmp_path / "out.txt"
    src.write_bytes(b"<p>from file</p>")
    p = run(["-f", str(src), "-o", str(dst), "p"])
    assert p.stdout == b""
    assert dst.read_bytes() == b"<p>from file</p>\n"

def test_missing_input_file_panics():
    p = run(["-f", "/definitely/not/a/file", "div"])
    assert p.returncode == 101
    assert b"should have opened input file" in p.stderr
